def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 12.0 # OPT_PARAM: {"type":"float","initial":12.0,"min":0.0,"max":60.0}
    demand_scale = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.6,"max":1.4}
    level_credit = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.2,"max":2.5}
    linear_age = 0.5 # OPT_PARAM: {"type":"float","initial":0.5,"min":-1.0,"max":4.0}
    quadratic_age = 0.0 # OPT_PARAM: {"type":"float","initial":0.0,"min":-1.0,"max":4.0}
    uncertain_credit = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":2.5}

    m = len(age)
    lead = int(L)
    stochastic = [0.0] * m
    fluid = [0.0] * m

    for i in range(m):
        x = float(age[i])
        if x < 0.0:
            x = 0.0
        stochastic[i] = x
        fluid[i] = x

    for t in range(lead):
        for stream in range(2):
            if stream == 0:
                g = float(f)
            else:
                g = 1.0 - float(f)

            if g > 0.0:
                M = g * float(mu)
                V = g * (float(mu) * float(cv)) ** 2
                a = V / (M * M) - 1.0 / M
                disc = a * a - 1.0
                if disc < 0.0:
                    disc = 0.0
                root = disc ** 0.5
                b = 1.0 + a + root
                c = 1.0 + a - root
                weight1 = 1.0 / b
                weight2 = 1.0 - weight1
                p1 = 2.0 / (2.0 + M * b)
                p2 = 2.0 / (2.0 + M * c)
                r1 = 1.0 - p1
                r2 = 1.0 - p2

                new_state = [0.0] * m
                cumulative = 0.0
                phi_before = 0.0

                for k in range(m):
                    if stream == 0:
                        idx = k
                    else:
                        idx = m - 1 - k

                    bucket = stochastic[idx]
                    cumulative_after = cumulative + bucket
                    y = cumulative_after / demand_scale
                    n = int(y)
                    fraction = y - float(n)

                    if n > 0:
                        truncated1 = r1 * (1.0 - r1 ** n) / p1
                        truncated2 = r2 * (1.0 - r2 ** n) / p2
                    else:
                        truncated1 = 0.0
                        truncated2 = 0.0

                    h_integer = float(n) - weight1 * truncated1 - weight2 * truncated2
                    cdf_n = weight1 * (1.0 - r1 ** (n + 1)) + weight2 * (1.0 - r2 ** (n + 1))
                    phi_after = demand_scale * (h_integer + fraction * cdf_n)
                    remaining = phi_after - phi_before

                    if remaining < 0.0:
                        remaining = 0.0
                    if remaining > bucket:
                        remaining = bucket

                    new_state[idx] = remaining
                    cumulative = cumulative_after
                    phi_before = phi_after

                stochastic = new_state

                demand_left = demand_scale * M
                for k in range(m):
                    if stream == 0:
                        idx = k
                    else:
                        idx = m - 1 - k

                    bucket = fluid[idx]
                    if demand_left > 0.0:
                        if bucket <= demand_left:
                            fluid[idx] = 0.0
                            demand_left = demand_left - bucket
                        else:
                            fluid[idx] = bucket - demand_left
                            demand_left = 0.0

        shifted_stochastic = [0.0] * m
        shifted_fluid = [0.0] * m

        for i in range(m - 1):
            shifted_stochastic[i] = stochastic[i + 1]
            shifted_fluid[i] = fluid[i + 1]

        if t < len(pipeline):
            arrival = float(pipeline[t])
            if arrival < 0.0:
                arrival = 0.0
        else:
            arrival = 0.0

        shifted_stochastic[m - 1] = arrival
        shifted_fluid[m - 1] = arrival
        stochastic = shifted_stochastic
        fluid = shifted_fluid

    weighted_stochastic = 0.0
    weighted_fluid = 0.0

    for i in range(m):
        if m > 1:
            oldness = float(m - 1 - i) / float(m - 1)
        else:
            oldness = 0.0

        age_weight = level_credit * (
            1.0 + linear_age * oldness + quadratic_age * oldness * oldness
        )
        weighted_stochastic = weighted_stochastic + age_weight * stochastic[i]
        weighted_fluid = weighted_fluid + age_weight * fluid[i]

    projected_credit = weighted_fluid + uncertain_credit * (
        weighted_stochastic - weighted_fluid
    )
    q = S - projected_credit

    if q != q:
        q = 0.0
    if q < 0.0:
        q = 0.0
    if q > 1000000.0:
        q = 1000000.0

    return float(q)

def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 12.0 # OPT_PARAM: {"type":"float","initial":12.0,"min":0.0,"max":60.0}
    GAIN = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.1,"max":2.5}
    D_SCALE = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.5,"max":1.5}
    W_OLD = 0.6 # OPT_PARAM: {"type":"float","initial":0.6,"min":0.0,"max":3.0}
    W_SLOPE = 0.4 # OPT_PARAM: {"type":"float","initial":0.4,"min":-3.0,"max":3.0}

    m = len(age)
    x = [0.0] * m
    for i in range(m):
        v = float(age[i])
        if v != v or v < 0.0:
            v = 0.0
        if v > 1000000.0:
            v = 1000000.0
        x[i] = v

    horizon = int(L)
    for step in range(horizon):
        for group in range(2):
            if group == 0:
                g = float(f)
            else:
                g = 1.0 - float(f)

            if g > 0.0:
                M = g * float(mu)
                V = g * (float(mu) * float(cv)) ** 2
                a = V / (M * M) - 1.0 / M
                root = (a * a - 1.0) ** 0.5
                b = 1.0 + a + root
                c = 1.0 + a - root
                mix = 1.0 / b
                p1 = 2.0 / (2.0 + M * b)
                p2 = 2.0 / (2.0 + M * c)
                r1 = 1.0 - p1
                r2 = 1.0 - p2

                cumulative = 0.0
                previous_expected = 0.0
                for j in range(m):
                    if group == 0:
                        k = j
                    else:
                        k = m - 1 - j

                    cohort = x[k]
                    cumulative = cumulative + cohort
                    scaled_capacity = cumulative / D_SCALE
                    e1 = r1 * (1.0 - r1 ** scaled_capacity) / p1
                    e2 = r2 * (1.0 - r2 ** scaled_capacity) / p2
                    expected_used = D_SCALE * (mix * e1 + (1.0 - mix) * e2)
                    take = expected_used - previous_expected
                    if take < 0.0:
                        take = 0.0
                    if take > cohort:
                        take = cohort
                    x[k] = cohort - take
                    previous_expected = expected_used

        shifted = [0.0] * m
        for i in range(1, m):
            shifted[i - 1] = x[i]

        arrival = 0.0
        if step < len(pipeline):
            arrival = float(pipeline[step])
            if arrival != arrival or arrival < 0.0:
                arrival = 0.0
            if arrival > 1000000.0:
                arrival = 1000000.0
        if m > 0:
            shifted[m - 1] = arrival
        x = shifted

    effective_inventory = 0.0
    for i in range(m):
        if m > 1:
            relative_age = float(i) / float(m - 1)
        else:
            relative_age = 0.0
        weight = W_OLD + W_SLOPE * relative_age
        if weight < 0.0:
            weight = 0.0
        if weight > 3.0:
            weight = 3.0
        effective_inventory = effective_inventory + weight * x[i]

    order = GAIN * (S - effective_inventory)
    if order != order or order <= 0.0:
        return 0.0
    if order > 1000000.0:
        return 1000000.0
    return float(order)

def compute_order_amount(age, pipeline, mu, cv, f, L):
    import math

    S = 12.0 # OPT_PARAM: {"type":"float","initial":12.0,"min":0.0,"max":50.0}
    B = 20.0 # OPT_PARAM: {"type":"float","initial":20.0,"min":0.0,"max":60.0}
    K_proj = 0.75 # OPT_PARAM: {"type":"float","initial":0.75,"min":0.0,"max":1.5}
    K_ip = 0.25 # OPT_PARAM: {"type":"float","initial":0.25,"min":0.0,"max":1.5}
    old_proj = 0.40 # OPT_PARAM: {"type":"float","initial":0.40,"min":0.0,"max":1.5}
    old_ip = 0.70 # OPT_PARAM: {"type":"float","initial":0.70,"min":0.0,"max":1.5}
    age_power = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.15,"max":4.0}
    pipe_weight = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":1.5}

    m = len(age)
    orig = [0.0] * m
    x = [0.0] * m
    for i in range(m):
        v = float(age[i])
        if not math.isfinite(v) or v < 0.0:
            v = 0.0
        if v > 1000000.0:
            v = 1000000.0
        orig[i] = v
        x[i] = v

    npip = len(pipeline)
    pvec = [0.0] * npip
    for j in range(npip):
        v = float(pipeline[j])
        if not math.isfinite(v) or v < 0.0:
            v = 0.0
        if v > 1000000.0:
            v = 1000000.0
        pvec[j] = v

    mf = float(f) * float(mu)
    vf = float(f) * (float(mu) * float(cv)) ** 2
    if mf > 0.0:
        af = vf / (mf * mf) - 1.0 / mf
        sf = math.sqrt(max(0.0, af * af - 1.0))
        bf = 1.0 + af + sf
        cf = 1.0 + af - sf
        fw = 1.0 / bf
        fp1 = 2.0 / (2.0 + mf * bf)
        fp2 = 2.0 / (2.0 + mf * cf)
        fr1 = 1.0 - fp1
        fr2 = 1.0 - fp2
    else:
        fw = 0.0
        fr1 = 0.0
        fr2 = 0.0

    gl = 1.0 - float(f)
    ml = gl * float(mu)
    vl = gl * (float(mu) * float(cv)) ** 2
    if ml > 0.0:
        al = vl / (ml * ml) - 1.0 / ml
        sl = math.sqrt(max(0.0, al * al - 1.0))
        bl = 1.0 + al + sl
        cl = 1.0 + al - sl
        lw = 1.0 / bl
        lp1 = 2.0 / (2.0 + ml * bl)
        lp2 = 2.0 / (2.0 + ml * cl)
        lr1 = 1.0 - lp1
        lr2 = 1.0 - lp2
    else:
        lw = 0.0
        lr1 = 0.0
        lr2 = 0.0

    lead = int(L)
    if lead < 0:
        lead = 0

    for step in range(lead):
        total = 0.0
        for i in range(m):
            total = total + x[i]

        survivor = [0.0] * m
        if total > 0.0:
            left = 0.0
            for i in range(m):
                amount = x[i]
                if amount > 0.0:
                    pieces = int(math.ceil(amount))
                    if pieces < 1:
                        pieces = 1
                    if pieces > 96:
                        pieces = 96
                    width = amount / float(pieces)
                    remaining = 0.0

                    for z in range(pieces):
                        position = left + (float(z) + 0.5) * width
                        above = total - position

                        if mf <= 0.0:
                            fifo_survival = 1.0
                        else:
                            ef = int(math.ceil(position))
                            fifo_survival = 1.0 - fw * (fr1 ** ef) - (1.0 - fw) * (fr2 ** ef)
                            if fifo_survival < 0.0:
                                fifo_survival = 0.0
                            if fifo_survival > 1.0:
                                fifo_survival = 1.0

                        if ml <= 0.0:
                            lifo_survival = 1.0
                        else:
                            el = int(math.ceil(above))
                            lifo_survival = 1.0 - lw * (lr1 ** el) - (1.0 - lw) * (lr2 ** el)
                            if lifo_survival < 0.0:
                                lifo_survival = 0.0
                            if lifo_survival > 1.0:
                                lifo_survival = 1.0

                        remaining = remaining + width * fifo_survival * lifo_survival

                    survivor[i] = remaining
                left = left + amount

        nxt = [0.0] * m
        for i in range(m - 1):
            nxt[i] = survivor[i + 1]

        if step < lead - 1 and step < npip:
            nxt[m - 1] = pvec[step]
        else:
            nxt[m - 1] = 0.0
        x = nxt

    projected_effective = 0.0
    current_effective = 0.0
    if m > 0:
        for i in range(m):
            relative_age = float(i + 1) / float(m)
            shape = relative_age ** age_power
            wp = old_proj + (1.0 - old_proj) * shape
            wi = old_ip + (1.0 - old_ip) * shape
            projected_effective = projected_effective + wp * x[i]
            current_effective = current_effective + wi * orig[i]

    pipeline_total = 0.0
    for j in range(npip):
        pipeline_total = pipeline_total + pvec[j]
    current_effective = current_effective + pipe_weight * pipeline_total

    projected_gap = S - projected_effective
    if projected_gap < 0.0:
        projected_gap = 0.0

    ip_gap = B - current_effective
    if ip_gap < 0.0:
        ip_gap = 0.0

    order = K_proj * projected_gap + K_ip * ip_gap
    if not math.isfinite(order) or order < 0.0:
        return 0.0
    return float(order)
